import json
import sys
import os
from pathlib import Path

# Aggiungi la directory padre al path per permettere l'import da qualsiasi directory
backend_dir = Path(__file__).resolve().parent.parent
if str(backend_dir) not in sys.path:
    sys.path.insert(0, str(backend_dir))

from blockchain.config import w3, ACCOUNT
from web3 import Web3

# Determina il percorso del file ABI relativo alla directory di esecuzione
abi_path = Path(__file__).resolve().parent / "abi.json"
if not abi_path.exists():
    abi_path = Path("blockchain/abi.json")

with open(abi_path) as f:
    abi = json.load(f)

bytecode = ""


def deploy_contract(validators):
    """
    Deploy del contratto HealthDataValidator su Quorum.
    
    Args:
        validators: List di indirizzi dei validatori
        
    Returns:
        address: Indirizzo del contratto deployato
    """
    
    print(f"📝 Creazione istanza contratto...")
    Contract = w3.eth.contract(abi=abi, bytecode=bytecode)
    
    # Converti validators a lista di checksum addresses
    validators_list = [Web3.to_checksum_address(v) if isinstance(v, str) else v for v in validators]
    print(f"📝 Validatori: {validators_list}")
    
    try:
        print(f"📝 Creazione transazione per il deploy...")
        
        # Ottieni il nonce dell'account
        nonce = w3.eth.get_transaction_count(ACCOUNT)
        print(f"📝 Nonce: {nonce}")
        print(f"📝 Account: {ACCOUNT}")
        print(f"📝 Gas Price: {w3.eth.gas_price}")
        
        # In Quorum RAFT, salta estimate_gas e usa un valore fisso più alto
        gas_limit = 5000000
        print(f"📝 Gas limit: {gas_limit}")
        
        # Crea la transazione
        tx_dict = {
            "from": ACCOUNT,
            "gas": gas_limit,
            "gasPrice": w3.eth.gas_price,
            "nonce": nonce
        }
        
        print(f"📝 Parametri transazione: {tx_dict}")
        
        tx_hash = Contract.constructor(validators_list).transact(tx_dict)
        
        print(f"📝 Transazione inviata: {tx_hash.hex()}")
        
        # Aspetta la conferma (Quorum RAFT tende ad essere veloce)
        receipt = w3.eth.wait_for_transaction_receipt(tx_hash, timeout=30)
        
        print(f"📝 Transazione confermata nel blocco {receipt.blockNumber}")
        print(f"📝 Gas usato: {receipt.gasUsed}")
        
        address = receipt.contractAddress
        
        if not address:
            raise Exception("❌ Indirizzo del contratto non ritornato")
        
        # Salva l'indirizzo usando percorso assoluto
        address_file = Path(__file__).resolve().parent / "address.json"
        with open(address_file, "w") as f:
            json.dump({"address": address}, f)
        
        print("✅ Contract deployato:", address)
        
        return address
        
    except Exception as e:
        print(f"❌ Errore durante il deploy: {str(e)}")
        raise


if __name__ == "__main__":
    import sys
    
    if len(sys.argv) > 1:
        # Se forniti validatori come argomenti
        validators = sys.argv[1:]
    else:
        # Usa gli account disponibili dal nodo
        try:
            validators = w3.eth.accounts
            if not validators:
                validators = [ACCOUNT]
        except:
            validators = [ACCOUNT]
    
    print(f"\n🚀 Avvio deploy del contratto con {len(validators)} validatori")
    address = deploy_contract(validators)
    print(f"\n✅ Deploy completato! Contratto a: {address}")